-- Generated from requirements workbook: initial payroll data
BEGIN;

CREATE TABLE IF NOT EXISTS employee_masters (employee_no VARCHAR(20) PRIMARY KEY, employee_name VARCHAR(100) NOT NULL, employee_type VARCHAR(50) NOT NULL, base_salary NUMERIC(15, 2) NOT NULL, dependent_count INTEGER NOT NULL, deduction_count INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS monthly_salary_calculation_conditions (employee_no VARCHAR(20) NOT NULL, payment_month VARCHAR(7) NOT NULL, commuting_allowance NUMERIC(15, 2), management_allowance NUMERIC(15, 2), transportation_adjustment NUMERIC(15, 2), overtime_pay NUMERIC(15, 2), advance_expense NUMERIC(15, 2), advance_expense2 NUMERIC(15, 2), other_amount NUMERIC(15, 2), other_item_name VARCHAR(100), PRIMARY KEY (employee_no, payment_month));
CREATE TABLE IF NOT EXISTS monthly_salary_details (employee_no VARCHAR(20) NOT NULL, payment_month VARCHAR(7) NOT NULL, employment_insurance_amount NUMERIC(15, 2), pension_insurance_amount NUMERIC(15, 2), health_insurance_amount NUMERIC(15, 2), income_tax NUMERIC(15, 2), child_support_amount NUMERIC(15, 2), taxable_income NUMERIC(15, 2), transfer_payment_amount NUMERIC(15, 2), PRIMARY KEY (employee_no, payment_month));
CREATE TABLE IF NOT EXISTS employee_resident_tax_details (employee_no VARCHAR(20) NOT NULL, payment_month VARCHAR(7) NOT NULL, payment_amount NUMERIC(15, 2) NOT NULL, PRIMARY KEY (employee_no, payment_month));


COMMIT;
